import sys
p = sys.argv[1]
s = open(p, encoding='utf-8', newline='').read()
def rep(old, new, cnt=1):
    global s
    assert s.count(old) == cnt, (old[:80], s.count(old))
    s = s.replace(old, new)
rep("# blake3-r3: plain birthday with 256 bit-sliced lanes, pivot full adders and a mask walk", "# blake3-r4: plain birthday with 256 bit-sliced lanes, pivot full adders and a mask walk")
i = s.index("Credited derivative of our own 0a9640ed"); j = s.index("## 1. Target and relation")
new_head = """Credited derivative of our own 62cfd777-5613-463f-b561-e2340e00e528 (blake3 round 3, 124.8123: this program at three rounds), of our own 0a9640ed-558a-4f0a-aba8-45e89ffcfd7c (blake3 round 3, bit-sliced 256-lane chain, 124.96822, passed the judges) and 3356413f-cd60-410c-8847-2266d6444ac5 (124.95448, two-block mode with a fixed first block; this entry does not use that mode), which are derivatives of our cf8b0e92-4302-4813-907a-3c970c102646 (125.10041) and of Jbenisek's e479cbbf-8aca-4fc6-bdc4-31b38d55c7ca (125.1087). It also uses two circuit and walk ideas from jungjipdo's 6ae36351-5836-4a46-ad34-227688264123 (124.91252), whose proof text (3.3, 3.4) we read as data and re-implemented in our own generator without using or running any file of that entry: (1) the pivot full adder, (2) the mask walk g = f XOR q in which the digest planes are fed back exactly as the circuit stores them. Everything else is the program of those entries: relation, trail-and-table search with distinguished points, handlers, recovery walk, ledger method, the register file and the 36-byte instruction charge.
The target is the plain one: the message is 64 bytes, 0^32 || x, one block, flags 11, standard IV; no prefix, no advice, no polarity climb, no scan. The chain step is {PH} operations for 256 trails ({perlane:.2f} per trail; 17,238 for the three-round step of 62cfd777). What four rounds change against the three-round entry: the straight line has {PH} gates and a program of {instr} instructions of 36 bytes ({codebytes} bytes) leaves {tablebytes} bytes ({tmax} entries of 26 bytes) for the table inside 2^20 bytes, so the trails are long (L = 2^{log2L:.2f}) and the unfinished trails at the halt cost a larger share; the circuit generator of the setup was rewritten in two passes without a node table so that it fits beside the larger program (Section 3.6); a trail length needs 16 bytes in a table entry (Section 7).

"""
s = s[:i] + new_head + s[j:]
rep("Target `blake3-r3-prefix-v1` (the benchmark's blake3 round-3 profile).", "Target `blake3-r4-prefix-v1` (the benchmark's blake3 round-4 profile).")
rep("flags 11 = CHUNK_START | CHUNK_END | ROOT, 3 rounds, digest = the 8 words v[i] XOR v[i+8] (i < 8), little endian (this is `verifier/blake3.py:blake3(M(x), 3)`).", "flags 11 = CHUNK_START | CHUNK_END | ROOT, 4 rounds with the BLAKE3 message permutation between rounds, digest = the 8 words v[i] XOR v[i+8] (i < 8), little endian (this is `verifier/blake3.py:blake3(M(x), 4)`).")
i = s.index("The scalar digest of the program (`digest_words`)"); j = s.index("## 2. The attack")
s = s[:i] + """The scalar digest of the program (`digest_words`) was compared outside the shipped experiments (`ext/ref_check.py` and `ext/ref_regress.py`, not shipped) with the organizer reference `verifier/blake3.py:blake3(M, r)` first at 3 rounds, then at 4 rounds (the target) and at the full 7 rounds, on {nchk} random 64-byte messages each (half of the form 0^32 || x): 0 differences. At 7 rounds the program's digest and the organizer reference were also compared with the `blake3` library (version 1.0.11) on 2,000 random 64-byte messages, the reference also on ten lengths from 0 to 3,000 bytes: 0 differences. The bit-sliced step was compared with the organizer reference `blake3(M(x), 4)` on {nref_step} random messages (one step: stored planes equal blake3(M(x), 4) XOR q) and on 4,096 lanes (16 x 256) chained for 4 steps, the packed recovery circuit on {nref_packed} messages, the scalar digest on {nref_scalar} messages: 0 differences in each. The program's own selftest (`python3 bsrho.py --selftest`) compares the step against the scalar compression on 4,096 lanes (16 batches of 256, the full 256-bit g), 4,096 lanes chained for 4 steps, the register-allocated code executed on a register file, the width-18 chain, the packed circuit, and prints the counts of shared and unused gates of the generator (both 0).

""" + s[j:]
rep("The key of a DP is the 56 bits of x above bit 121 followed by the 8 low bits of F (F < {Tp} < 2^8, so those 8 bits are F); 64 bits in all.", "The key of a DP is the {kb} bits of x above bit 121 followed by the {fb} low bits of F (F < {Tp} <= 2^{fb}, so those {fb} bits are F); 64 bits in all.")
rep("store (t, length) under the key (25-byte entry, Section 7)", "store (t, length) under the key (26-byte entry, Section 7)")
rep("every length is below c + S < 2^119, so the 2-byte and 15-byte fields of an entry never overflow", "every length is below c + S < 2^{log2capr1:.1f}, so the 2-byte and 16-byte fields of an entry never overflow")
rep("The organizer's reference count C(r3) = 638 (222, 430 and 638 for 1, 2 and 3 rounds) is used only as the unit: Unit = 638 operations.", "The organizer's reference count C(r4) = 846 (222, 430, 638 and 846 for 1 to 4 rounds, the value of the organizer's `pareto/targets.py:reference_cost('blake3', r)`) is used only as the unit: Unit = 846 operations.")
rep("The program generates the straight line at run time (`trace`, `Step`): gates are hash-consed, a gate whose result no output uses is dropped.", "The program generates the straight line at run time. At this target no two gates of the network are equal and every gate is used (the reference generator `Gen`/`Step`, which would share equal gates and drop unused ones, finds none: the selftest prints 0 shared and 0 unused gates), so the machine generator of Section 3.6 builds the network in two passes and keeps no node table.")
rep("Per trail {perlane:.3f} operations = {unit:.4f} unit, against 1 unit for a compression and 0.1332 unit for the packed circuit of cf8b0e92.", "Per trail {perlane:.3f} operations = {unit:.4f} unit, against 1 unit for a compression.")
rep("Validation: 4,096 lanes against the scalar digest in the selftest (stored planes = f XOR q); 8,192 lanes and 256 lanes chained for 4 steps against the organizer reference (Section 1);", "Validation: 4,096 lanes against the scalar digest in the selftest (stored planes = f XOR q); 8,192 lanes and 4,096 lanes chained for 4 steps against the organizer reference (Section 1);")
rep("three read-modify-write field stores of the 25-byte entry", "three read-modify-write field stores of the 26-byte entry")
rep("The generator: {gencalls} primitive calls (hash-consed gate constructors) and {PH} emitted lines, each charged 200 word operations: {gen}.", "The generator: {gencalls} primitive calls (two passes of {gencalls1} gate-constructor calls each) and {PH} emitted lines, each charged 200 word operations: {gen}.")
rep("Code size, instructions: loop body {body} + handlers 1,000 (256 stores, 256 reloads, the loops and the event logic) + recovery 650 (the {PH7}-operation circuit, the test, the loop, the call and the moves) + setup, cut and slice 160 = {instr} instructions.", "Code size, instructions: loop body {body} + handlers 1,000 (256 stores, 256 reloads, the loops and the event logic) + recovery {recov} (the {PH7}-operation circuit, the test, the loop, the call and the moves) + setup, cut and slice 160 = {instr} instructions.")
rep("N / 638 = {Nunits} units", "N / 846 = {Nunits} units")
open(p, 'w', encoding='utf-8', newline='').write(s)
print("ok")
